25	package jenkins.security;
26	
27	import static java.time.Instant.now;
28	import static java.time.Instant.ofEpochMilli;
29	import static java.time.temporal.ChronoUnit.MINUTES;
30	
31	import com.google.common.annotations.VisibleForTesting;
32	import edu.umd.cs.findbugs.annotations.CheckForNull;
33	import edu.umd.cs.findbugs.annotations.NonNull;
34	import edu.umd.cs.findbugs.annotations.Nullable;
35	import edu.umd.cs.findbugs.annotations.SuppressFBWarnings;
36	import hudson.Extension;
37	import hudson.ExtensionList;
38	import hudson.Util;
39	import hudson.model.DirectoryBrowserSupport;
40	import hudson.model.UnprotectedRootAction;
41	import hudson.model.User;
42	import hudson.security.ACL;
43	import hudson.security.ACLContext;
44	import java.io.IOException;
45	import java.nio.charset.StandardCharsets;
46	import java.time.Instant;
47	import java.util.Arrays;
48	import java.util.Base64;
49	import java.util.logging.Level;
50	import java.util.logging.Logger;
51	import java.util.stream.Collectors;
52	import jenkins.model.Jenkins;
53	import jenkins.util.SystemProperties;
54	import org.kohsuke.accmod.Restricted;
55	import org.kohsuke.accmod.restrictions.NoExternalUse;
56	import org.kohsuke.stapler.Stapler;
57	import org.kohsuke.stapler.StaplerRequest;
58	import org.kohsuke.stapler.StaplerResponse;
59	import org.springframework.security.access.AccessDeniedException;
60	import org.springframework.security.core.Authentication;
61	import org.springframework.security.core.userdetails.UsernameNotFoundException;
62	
63	/**
64	 * Root action serving {@link DirectoryBrowserSupport} instances
65	 * on random URLs to support resource URLs (second domain).
66	 *
67	 * @see ResourceDomainConfiguration
68	 * @see ResourceDomainFilter
69	 *
70	 * @since 2.200
71	 */
72	@Extension
73	@Restricted(NoExternalUse.class)
74	public class ResourceDomainRootAction implements UnprotectedRootAction {
75	
76	    private static final String RESOURCE_DOMAIN_ROOT_ACTION_ERROR = "jenkins.security.ResourceDomainRootAction.error";
77	
78	    private static final Logger LOGGER = Logger.getLogger(ResourceDomainRootAction.class.getName());
79	
80	    public static final String URL = "static-files";
81	
82	    @CheckForNull
83	    @Override
84	    public String getIconFileName() {
85	        return null;
86	    }
87	
88	    @CheckForNull
89	    @Override
90	    public String getDisplayName() {
91	        return null;
92	    }
93	
94	    @CheckForNull
95	    @Override
96	    public String getUrlName() {
97	        return URL;
98	    }
99	
100	    public static ResourceDomainRootAction get() {
101	        return ExtensionList.lookupSingleton(ResourceDomainRootAction.class);
102	    }
103	
104	    public void doIndex(StaplerRequest req, StaplerResponse rsp) throws IOException {
105	        if (ResourceDomainConfiguration.isResourceRequest(req)) {
106	            rsp.sendError(404, ResourceDomainFilter.ERROR_RESPONSE);
107	        } else {
108	            req.setAttribute(RESOURCE_DOMAIN_ROOT_ACTION_ERROR, true);
109	            rsp.sendError(404, "Cannot handle requests to this URL unless on Jenkins resource URL.");
110	        }
111	    }
112	
113	    public Object getDynamic(String id, StaplerRequest req, StaplerResponse rsp) throws Exception {
114	        if (!ResourceDomainConfiguration.isResourceRequest(req)) {
115	            req.setAttribute(RESOURCE_DOMAIN_ROOT_ACTION_ERROR, true);
116	            rsp.sendError(404, "Cannot handle requests to this URL unless on Jenkins resource URL.");
117	            return null;
118	        }
119	
120	        if (!ACL.isAnonymous2(Jenkins.getAuthentication2())) {
121	            rsp.sendError(400);
122	            return null;
123	        }
124	
125	        Token token = Token.decode(id);
126	        if (token == null) {
127	            rsp.sendError(404, ResourceDomainFilter.ERROR_RESPONSE);
128	            return null;
129	        }
130	
131	        String authenticationName = token.username;
132	        String browserUrl = token.path;
133	
134	
135	        if (token.timestamp.plus(VALID_FOR_MINUTES, MINUTES).isAfter(now()) && token.timestamp.isBefore(now())) {
136	            return new InternalResourceRequest(browserUrl, authenticationName);
137	        }
138	
139	        // too old, so redirect to the real file first
140	        return new Redirection(browserUrl);
141	    }
142	
143	    private static class Redirection {
144	        private final String url;
145	
146	        private Redirection(String url) {
147	            this.url = url;
148	        }
149	
150	        public void doDynamic(StaplerRequest req, StaplerResponse rsp) throws IOException {
151	            String restOfPath = req.getRestOfPath();
152	
153	            String url = Jenkins.get().getRootUrl() + this.url + restOfPath;
154	            rsp.sendRedirect(302, url);
155	        }
156	    }
157	
158	    public String getRedirectUrl(@NonNull Token token, @NonNull String restOfPath) {
159	        String resourceRootUrl = getResourceRootUrl();
160	        if (!restOfPath.startsWith("/")) {
161	            // Unsure whether this can happen -- just be safe here
162	            restOfPath = "/" + restOfPath;
163	        }
164	        return resourceRootUrl + getUrlName() + "/" + token.encode() + Arrays.stream(restOfPath.split("[/]")).map(Util::rawEncode).collect(Collectors.joining("/"));
165	    }
166	
167	    private static String getResourceRootUrl() {
168	        return ResourceDomainConfiguration.get().getUrl();
169	    }
170	
171	    /**
172	     * Called from {@link DirectoryBrowserSupport#generateResponse(StaplerRequest, StaplerResponse, Object)} to obtain
173	     * a token to use when rendering a response.
174	     *
175	     * @param dbs the {@link DirectoryBrowserSupport} instance requesting the token
176	     * @param req the current request
177	     * @return a token that can be used to redirect users to the {@link ResourceDomainRootAction}.
178	     */
179	    @CheckForNull
180	    public Token getToken(@NonNull DirectoryBrowserSupport dbs, @NonNull StaplerRequest req) {
181	        // This is the "restOfPath" of the DirectoryBrowserSupport, i.e. the directory/file/pattern "inside" the DBS.
182	        final String dbsFile = req.getOriginalRestOfPath();
183	
184	        // Now get the 'restOfUrl' after the top-level ancestor (which is the Jenkins singleton).
185	        // In other words, this is the complete URL after Jenkins handled the top-level request.
186	        final String completeUrl = req.getAncestors().get(0).getRestOfUrl();
187	
188	        // And finally, remove the 'restOfPath' suffix from the complete URL, as that's the path from Jenkins to the DBS.
189	        String dbsUrl = completeUrl.substring(0, completeUrl.length() - dbsFile.length());
190	        LOGGER.fine(() -> "Determined DBS URL: " + dbsUrl + " from restOfUrl: " + completeUrl + " and restOfPath: " + dbsFile);
191	
192	        Authentication authentication = Jenkins.getAuthentication2();
193	        String authenticationName = authentication.equals(Jenkins.ANONYMOUS2) ? "" : authentication.getName();
194	
195	        try {
196	            return new Token(dbsUrl, authenticationName, Instant.now());
197	        } catch (RuntimeException ex) {
198	            LOGGER.log(Level.WARNING, "Failed to encode token for URL: " + dbsUrl + " user: " + authenticationName, ex);
199	        }
200	        return null;
201	    }
202	
203	    /**
204	     * Implements the browsing support for a specific {@link DirectoryBrowserSupport} like permission check.
205	     */
206	    private static class InternalResourceRequest {
207	        private final String authenticationName;
208	        private final String browserUrl;
209	
210	        InternalResourceRequest(@NonNull String browserUrl, @NonNull String authenticationName) {
211	            this.browserUrl = browserUrl;
212	            this.authenticationName = authenticationName;
213	        }
214	
215	        public void doDynamic(StaplerRequest req, StaplerResponse rsp) throws IOException {
216	            String restOfPath = req.getRestOfPath();
217	
218	            String requestUrlSuffix = this.browserUrl;
219	
220	            LOGGER.fine(() -> "Performing a request as authentication: " + authenticationName + " and restOfUrl: " + requestUrlSuffix + " and restOfPath: " + restOfPath);
221	
222	            Authentication auth = Jenkins.ANONYMOUS2;
223	            if (Util.fixEmpty(authenticationName) != null) {
224	                User user = User.getById(authenticationName, false);
225	                if (user != null) {
226	                    try {
227	                        auth = user.impersonate2();
228	                        LOGGER.fine(() -> "Successfully impersonated " + authenticationName);
229	                    } catch (UsernameNotFoundException ex) {
230	                        LOGGER.log(Level.FINE, "Failed to impersonate " + authenticationName, ex);
231	                        rsp.sendError(403, "No such user: " + authenticationName);
232	                        return;
233	                    }
234	                }
235	            }
236	
237	            try (ACLContext ignored = ACL.as2(auth)) {
238	                try {
239	                    String path = requestUrlSuffix + Arrays.stream(restOfPath.split("[/]")).map(Util::rawEncode).collect(Collectors.joining("/"));
240	                    Stapler.getCurrent().invoke(req, rsp, Jenkins.get(), path);
241	                } catch (Exception ex) {
242	                    // cf. UnwrapSecurityExceptionFilter
243	                    Throwable cause = ex.getCause();
244	                    while (cause != null) {
245	                        if (cause instanceof AccessDeniedException) {
246	                            throw (AccessDeniedException) cause;
247	                        }
248	                        cause = cause.getCause();
249	                    }
250	                    throw ex;
251	                }
252	                /*
253	                While we could just redirect below to the real URL like we do for expired resource URLs, the question
254	                is whether we'd end up in a redirect loop if the exception is specific to this mode (and the "normal"
255	                URLs redirect to resource URLs). That seems even worse than an error here.
256	                 */
257	            } catch (AccessDeniedException ade) {
258	                /* This is expected to be fairly common, as permission issues are thrown up as exceptions */
259	                LOGGER.log(Level.FINE, "Failed permission check for resource URL access", ade);
260	                rsp.sendError(403, "Failed permission check: " + ade.getMessage());
261	            } catch (Exception e) {
262	                /*
263	                This should be fairly uncommon -- it's basically the 'rage' butler response. Notably, lack of access
264	                to a job (permissions/deleted/renamed/...) would not throw an exception, but just sends a 404 response.
265	                 */
266	                LOGGER.log(Level.FINE, "Something else failed for resource URL access", e);
267	                rsp.sendError(404);
268	            }
269	        }
270	
271	        @Override
272	        public String toString() {
273	            return "[" + super.toString() + ", authentication=" + authenticationName + "; key=" + browserUrl + "]";
274	        }
275	    }
276	
277	    public static class Token {
278	        private String path;
279	        private String username;
280	        private Instant timestamp;
281	
282	        @VisibleForTesting
283	        Token(@NonNull String path, @Nullable String username, @NonNull Instant timestamp) {
284	            this.path = path;
285	            this.username = Util.fixNull(username);
286	            this.timestamp = timestamp;
287	        }
288	
289	        private String encode() {
290	            String value = timestamp.toEpochMilli() + ":" + username.length() + ":" + username + ":" + path;
291	            byte[] valueBytes = value.getBytes(StandardCharsets.UTF_8);
292	            byte[] macBytes = KEY.mac(valueBytes);
293	            byte[] result = new byte[macBytes.length + valueBytes.length];
294	            System.arraycopy(macBytes, 0, result, 0, macBytes.length);
295	            System.arraycopy(valueBytes, 0, result, macBytes.length, valueBytes.length);
296	            return Base64.getUrlEncoder().encodeToString(result);
297	        }
298	
299	        private static Token decode(String value) {
300	            try {
301	                byte[] byteValue = Base64.getUrlDecoder().decode(value);
302	                byte[] mac = Arrays.copyOf(byteValue, 32);
303	                byte[] restBytes = Arrays.copyOfRange(byteValue, 32, byteValue.length);
304	                String rest = new String(restBytes, StandardCharsets.UTF_8);
305	                if (!KEY.checkMac(restBytes, mac)) {
306	                    throw new IllegalArgumentException("Failed mac check for " + rest);
307	                }
308	
309	                String[] splits = rest.split("[:]", 3);
310	                String epoch = splits[0];
311	                int authenticationNameLength = Integer.parseInt(splits[1]);
312	                String authenticationNameAndBrowserUrl = splits[2];
313	                String authenticationName = authenticationNameAndBrowserUrl.substring(0, authenticationNameLength);
314	                String browserUrl = authenticationNameAndBrowserUrl.substring(authenticationNameLength + 1);
315	                return new Token(browserUrl, authenticationName, ofEpochMilli(Long.parseLong(epoch)));
316	            } catch (RuntimeException ex) {
317	                // Choose log level that hides people messing with the URLs
318	                LOGGER.log(Level.FINE, "Failure decoding", ex);
319	                return null;
320	            }
321	        }
322	
323	    }
324	
325	    private static HMACConfidentialKey KEY = new HMACConfidentialKey(ResourceDomainRootAction.class, "key");
326	
327	    // Not @Restricted because the entire class is
328	    @SuppressFBWarnings(value = "MS_SHOULD_BE_FINAL", justification = "for script console")
329	    public static /* not final for Groovy */ int VALID_FOR_MINUTES = SystemProperties.getInteger(ResourceDomainRootAction.class.getName() + ".validForMinutes", 30);
330	}
